-- PRASYARAT abt-tanggal-agenda-31okt (BACA SAJA). Satu baris A|B:
--  A = variabel 7111,7115,7112,7116,7113,7117,7114,7118,8438,7122,2111,7119,2112,7121 yang isinya PERSIS keadaan sebelum paket (14 sebelum, 0 sesudah)
--  B = variabel yang sama yang isinya PERSIS hasil paket (0 sebelum, 14 sesudah)
-- Pasang bila 14|0; pasang ulang bila 0|14; selain itu berhenti tanpa mengubah apa pun.
SELECT CONCAT_WS('|',
 (SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (7111,7115,7112,7116,7113,7117,7114,7118,8438,7122,2111,7119,2112,7121) AND MD5(REPLACE(sql_query, CONCAT(DATABASE(), '.'), 'aps_badilag.')) IN ('c2638d62a413b68b0a0dafa26e4dcfae','b57de066ea2d55438aa02b797f7d802c','18f108e154d4a89f7f7fd8674ab749b2','e057ecf9841395bf6ba5f06ae8ca29c4','b8221a4e8e7240cbc78bbe073f19d9d1','3da6b6d6c016b1a431b7b5d37763fe86','4bccf006afb50051a0dbca10619d58dd','930900d54f01aa07bafd6698ca35d9cf','34e10f306c283a7b5ca44c99be4c8d19','667a01a5f7a989276ddfecc98985a985','345e077634d96fd834610fb2f045c39e','2e3abf2c02022cbf755282bf2cace8de','d3f457cdc9a992c1e746db420bc00baa','266d948678b61337c3e939214d6a981d')),
 (SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (7111,7115,7112,7116,7113,7117,7114,7118,8438,7122,2111,7119,2112,7121) AND MD5(REPLACE(sql_query, CONCAT(DATABASE(), '.'), 'aps_badilag.')) IN ('ada6e46ff400402fd94d30f0fc86b218','ec3f984f7baf39aa647bca5c8b40b436','9bf9f023688a3d6ba7417482d207d1af','c55c82cc2ca1e5e42cff29e537bb3e86','70dfb5a7af49266190bf55d966b57692','ee703c6b908bffc77740e030680dbd6c','5e45e1ac9790879923f7284360e45466','62147fd29f51e0d8c42de240b5a7a6a6','d5c64705761662fa97742848c1c08080','21c7891a4fee988d0b78c1cae22c1953','d5e7da09924ad1dca1d1ec1da6ffecaf','194ecb54d1e0e51e9ad01fb98a1b2b1a','5ddc77c251033ae93e637cedf897919d','5aa4c9f937d2d9a6176736260319165b'))
) AS prasyarat;
